    const locked = await this.api.lock(sheet, claim.id);
    this.saved.emit(locked);
    if (previous !== null && previous !== claim.id) void this.release(sheet, previous);
    if (this.editing() === claim.id && !this.typedSinceOpen) this.fill(locked);
